def must(path, old, new):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit(f'v1.6.4 anchor missing in {p}: {old[:220]!r}')
    p.write_text(s.replace(old,new,1))

def opt(path, old, new):
    p=Path(path); s=p.read_text()
    if old in s: p.write_text(s.replace(old,new,1))

# ---------------------------------------------------------------------------
# Two-stage forward confirmation and momentum-decay protection.
# ---------------------------------------------------------------------------
(ROOT/'ForwardConfirmationLogic.java').write_text('''package com.suhas.nseunifiedscanner;\n\n/** Pure 1-minute confirmation logic: pressure must persist instead of flashing once. */\nfinal class ForwardConfirmationLogic {\n    private ForwardConfirmationLogic(){}\n    static boolean persistence(double lastClose,double prevClose,double lastLow,double prevLow,double lastVol,double prevVol,double prev2Vol,boolean macdAccel,boolean higherLows,double price3mPct,double microBreakoutPct){\n        if(!(lastClose>0)||!(prevClose>0))return false;\n        double prevAvg=Math.max(0,(Math.max(0,prevVol)+Math.max(0,prev2Vol))/2.0);\n        boolean volumeHolds=prevAvg<=0 || lastVol>=prevAvg*0.55;\n        boolean priceHolds=lastClose>=prevClose*0.9985 && (!(prevLow>0)||lastLow>=prevLow*0.9975);\n        boolean trigger=price3mPct>=0.03 || microBreakoutPct>=-0.08 || (macdAccel&&higherLows);\n        return volumeHolds && priceHolds && trigger && (macdAccel||higherLows);\n    }\n    static boolean momentumDecay(double currentAccel,double previousAccel,double price3mPct,double lastClose,double prevClose){\n        boolean volumeCollapse=previousAccel>=1.35 && currentAccel<Math.max(0.85,previousAccel*0.60);\n        boolean priceFade=price3mPct<-0.15 || (lastClose>0&&prevClose>0&&lastClose<prevClose*0.9970);\n        return volumeCollapse || (priceFade && currentAccel<1.10);\n    }\n}\n''')
(TEST/'ForwardConfirmationLogicTest.java').write_text('''package com.suhas.nseunifiedscanner;\nimport org.junit.Test;\nimport static org.junit.Assert.*;\npublic class ForwardConfirmationLogicTest {\n @Test public void persistentPressurePasses(){assertTrue(ForwardConfirmationLogic.persistence(100.12,100.08,99.98,99.95,1800,2000,1700,true,true,0.11,-0.03));}\n @Test public void collapsingLastMinuteVolumeFailsPersistence(){assertFalse(ForwardConfirmationLogic.persistence(100.10,100.08,99.98,99.95,400,2000,1800,true,true,0.10,-0.02));}\n @Test public void sharpAccelerationCollapseIsDecay(){assertTrue(ForwardConfirmationLogic.momentumDecay(0.82,2.20,0.05,100.1,100.0));}\n @Test public void stableAccelerationIsNotDecay(){assertFalse(ForwardConfirmationLogic.momentumDecay(1.70,1.90,0.08,100.1,100.0));}\n}\n''')

# Pattern-memory logic is intentionally separate from the adaptive logistic weights.
(ROOT/'PatternMemoryLogic.java').write_text('''package com.suhas.nseunifiedscanner;\n\nimport java.util.List;\n\nfinal class PatternMemoryLogic {\n    private PatternMemoryLogic(){}\n    static final class Snapshot {\n        String setup=""; double early,volAccel,rsi,breadth,weight=1.0; boolean hodRejected,hit;\n    }\n    static final class Evidence {\n        int n,hits; double posterior; boolean veto,strong;\n        Evidence(int n,int hits,double posterior){this.n=n;this.hits=hits;this.posterior=posterior;veto=n>=10&&posterior<0.36;strong=n>=12&&posterior>=0.55;}\n    }\n    static Evidence evaluate(String setup,double early,double volAccel,double rsi,double breadth,boolean hodRejected,List<Snapshot> history){\n        int n=0,hits=0;double wn=0,wh=0;String regime=regime(breadth);\n        if(history!=null)for(Snapshot s:history){\n            int sim=0;if(norm(setup).equals(norm(s.setup)))sim+=2;if(regime.equals(regime(s.breadth)))sim++;if(Math.abs(early-s.early)<=12.0)sim++;\n            double a=Math.max(0.15,volAccel),b=Math.max(0.15,s.volAccel);if(Math.abs(Math.log(a/b))<=Math.log(1.90))sim++;\n            boolean rsiKnown=rsi>0&&s.rsi>0;if(rsiKnown&&Math.abs(rsi-s.rsi)<=8.0)sim++;if(hodRejected==s.hodRejected)sim++;\n            int need=rsiKnown?5:4;if(sim<need)continue;n++;if(s.hit)hits++;double w=Math.max(0.25,Math.min(2.0,s.weight));wn+=w;if(s.hit)wh+=w;\n        }\n        // Beta(2,3) prior = 40%; enough to avoid overreacting to tiny buckets.\n        double post=(wh+2.0)/(wn+5.0);return new Evidence(n,hits,post);\n    }\n    static String regime(double breadth){return breadth>=60?"BULL":breadth<=40?"WEAK":"MIXED";}\n    private static String norm(String s){return s==null?"":s.trim().toUpperCase();}\n}\n''')
(TEST/'PatternMemoryLogicTest.java').write_text('''package com.suhas.nseunifiedscanner;\nimport java.util.*;import org.junit.Test;import static org.junit.Assert.*;\npublic class PatternMemoryLogicTest {\n private PatternMemoryLogic.Snapshot s(boolean hit){PatternMemoryLogic.Snapshot x=new PatternMemoryLogic.Snapshot();x.setup="PRE-SPIKE";x.early=88;x.volAccel=1.8;x.rsi=56;x.breadth=66;x.hodRejected=false;x.hit=hit;return x;}\n @Test public void weakRepeatedPatternVetoes(){List<PatternMemoryLogic.Snapshot>a=new ArrayList<>();for(int i=0;i<12;i++)a.add(s(i<2));PatternMemoryLogic.Evidence e=PatternMemoryLogic.evaluate("PRE-SPIKE",90,1.7,55,68,false,a);assertTrue(e.veto);}\n @Test public void strongPatternIsFlagged(){List<PatternMemoryLogic.Snapshot>a=new ArrayList<>();for(int i=0;i<14;i++)a.add(s(i<11));PatternMemoryLogic.Evidence e=PatternMemoryLogic.evaluate("PRE-SPIKE",90,1.7,55,68,false,a);assertTrue(e.strong);assertFalse(e.veto);}\n @Test public void tinySampleDoesNotVeto(){List<PatternMemoryLogic.Snapshot>a=new ArrayList<>();for(int i=0;i<5;i++)a.add(s(false));PatternMemoryLogic.Evidence e=PatternMemoryLogic.evaluate("PRE-SPIKE",90,1.7,55,68,false,a);assertFalse(e.veto);}\n}\n''')

