insert='''\n    synchronized List<PatternMemoryLogic.Snapshot> recentPatternSamples(int limit){\n        List<PatternMemoryLogic.Snapshot> out=new ArrayList<>();int lim=Math.max(50,Math.min(1500,limit));\n        try(SQLiteDatabase db=open();Cursor c=db.rawQuery("SELECT status,features FROM shadow_samples WHERE status IN ('SUCCESS','FAIL','TIMEOUT') ORDER BY resolved_ms DESC LIMIT "+lim,null)){\n            while(c.moveToNext()){PatternMemoryLogic.Snapshot s=patternSnapshot(c.getString(0),c.getString(1),1.0);if(s!=null)out.add(s);}\n        }catch(Exception ignore){}\n        try(SQLiteDatabase db=open();Cursor c=db.rawQuery("SELECT status,features FROM recommendations WHERE status IN ('SUCCESS','FAIL','TIMEOUT') ORDER BY resolved_ms DESC LIMIT 120",null)){\n            while(c.moveToNext()){PatternMemoryLogic.Snapshot s=patternSnapshot(c.getString(0),c.getString(1),1.75);if(s!=null)out.add(s);}\n        }catch(Exception ignore){}\n        return out;\n    }\n\n    private static PatternMemoryLogic.Snapshot patternSnapshot(String status,String raw,double weight){\n        try{JSONObject f=new JSONObject(raw);PatternMemoryLogic.Snapshot s=new PatternMemoryLogic.Snapshot();s.setup=f.optString("setupType","");s.early=f.optDouble("earlyPressure",0);s.volAccel=f.optDouble("volumeAccel",0);s.rsi=f.optDouble("rsi1m",0);s.breadth=f.optDouble("breadthPct",0);s.hodRejected=f.optBoolean("hodRejected",false);s.hit="SUCCESS".equals(status);s.weight=weight;return s;}catch(Exception e){return null;}\n    }\n\n'''
